create table public.pre_cadastros_v141(
 id uuid primary key default gen_random_uuid(), criado_por uuid not null references auth.users(id),
 nome_responsavel text not null,email text not null,secao_id bigint not null references public.secoes(id),
 status text not null default 'rascunho' check(status in('rascunho','enviado','ajustes','conferido','paxtu','boleto','aguardando_ueb','liberado','cancelado')),
 dados jsonb not null default '{}',orientacao text,criado_em timestamptz not null default now(),atualizado_em timestamptz not null default now(),enviado_em timestamptz,
 emergencia_ciente_em timestamptz,emergencia_termo_versao integer,jovem_id bigint references public.jovens(id),responsavel_id bigint references public.responsaveis(id),registro_ueb text,validade_registro date,
 check(jsonb_typeof(dados)='object' and octet_length(dados::text)<=150000)
);
alter table public.pre_cadastros_v141 enable row level security;
revoke all on public.pre_cadastros_v141 from public,anon,authenticated;
grant select on public.pre_cadastros_v141 to authenticated;
create policy prereg_admin_read on public.pre_cadastros_v141 for select to authenticated using(private.sou_admin());
create table private.pre_cadastro_acessos_v141(
 id uuid primary key references public.pre_cadastros_v141(id) on delete cascade,
 token_hash text not null unique,senha_hash text,expira_em timestamptz not null default now()+interval '30 days',
 tentativas integer not null default 0,bloqueado_ate timestamptz,session_hash text,session_expira timestamptz
);
alter table private.pre_cadastro_acessos_v141 enable row level security;
revoke all on private.pre_cadastro_acessos_v141 from public,anon,authenticated;
alter table public.jovens add column if not exists dados_cadastrais jsonb not null default '{}';
alter table public.responsaveis add column if not exists dados_cadastrais jsonb not null default '{}';

create function public.criar_pre_cadastro_v141(p_nome text,p_email text,p_secao bigint)
returns jsonb language plpgsql security definer set search_path='' as $fn$
declare v_id uuid;v_token text;
begin
 if auth.uid() is null or not private.sou_admin() then raise exception 'Acesso reservado à administração' using errcode='42501';end if;
 if length(btrim(coalesce(p_nome,'')))<3 or p_email !~ '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$' then raise exception 'Informe nome e e-mail válidos';end if;
 if not exists(select 1 from public.secoes where id=p_secao and ativo) then raise exception 'Selecione uma seção ativa';end if;
 if exists(select 1 from public.pre_cadastros_v141 where lower(email)=lower(btrim(p_email)) and status not in('cancelado','liberado')) then raise exception 'Já há um pré-cadastro aberto para este e-mail. Abra o cadastro existente';end if;
 v_token:=encode(extensions.gen_random_bytes(32),'hex');
 insert into public.pre_cadastros_v141(criado_por,nome_responsavel,email,secao_id,dados) values(auth.uid(),btrim(p_nome),lower(btrim(p_email)),p_secao,jsonb_build_object('responsavel',jsonb_build_object('nome',btrim(p_nome),'email',lower(btrim(p_email))))) returning id into v_id;
 insert into private.pre_cadastro_acessos_v141(id,token_hash) values(v_id,encode(extensions.digest(v_token,'sha256'),'hex'));
 return jsonb_build_object('id',v_id,'token',v_token);
end $fn$;
revoke all on function public.criar_pre_cadastro_v141(text,text,bigint) from public,anon;
grant execute on function public.criar_pre_cadastro_v141(text,text,bigint) to authenticated;

create function public.acessar_pre_cadastro_v141(p_token text,p_senha text)
returns jsonb language plpgsql security definer set search_path='' as $fn$
declare a private.pre_cadastro_acessos_v141%rowtype;v_session text;
begin
 if p_token is null or length(p_token)<>64 or length(coalesce(p_senha,'')) not between 8 and 72 then return jsonb_build_object('erro','Informe o link individual e uma senha de 8 a 72 caracteres');end if;
 select * into a from private.pre_cadastro_acessos_v141 where token_hash=encode(extensions.digest(p_token,'sha256'),'hex') for update;
 if not found or a.expira_em<now() or exists(select 1 from public.pre_cadastros_v141 where id=a.id and status='cancelado') then return jsonb_build_object('erro','Link inválido, cancelado ou expirado. Peça um novo link à administração');end if;
 if a.bloqueado_ate>now() then return jsonb_build_object('erro','Muitas tentativas. Aguarde 15 minutos antes de tentar novamente');end if;
 if a.senha_hash is not null and a.senha_hash<>extensions.crypt(p_senha,a.senha_hash) then
   update private.pre_cadastro_acessos_v141 set tentativas=case when tentativas>=4 then 0 else tentativas+1 end,bloqueado_ate=case when tentativas>=4 then now()+interval '15 minutes' else null end where id=a.id;
   return jsonb_build_object('erro','Senha incorreta');
 end if;
 v_session:=encode(extensions.gen_random_bytes(32),'hex');
 update private.pre_cadastro_acessos_v141 set senha_hash=coalesce(senha_hash,extensions.crypt(p_senha,extensions.gen_salt('bf',10))),tentativas=0,bloqueado_ate=null,session_hash=encode(extensions.digest(v_session,'sha256'),'hex'),session_expira=now()+interval '12 hours' where id=a.id;
 return jsonb_build_object('sessao',v_session,'id',a.id);
end $fn$;
revoke all on function public.acessar_pre_cadastro_v141(text,text) from public;
grant execute on function public.acessar_pre_cadastro_v141(text,text) to anon,authenticated;

create function private.pre_cadastro_da_sessao_v141(p_sessao text)
returns uuid language plpgsql security definer set search_path='' as $fn$
declare v_id uuid;
begin
 if p_sessao is null or length(p_sessao)<>64 then raise exception 'Entre novamente pelo link individual' using errcode='42501';end if;
 select a.id into v_id from private.pre_cadastro_acessos_v141 a join public.pre_cadastros_v141 c on c.id=a.id where a.session_hash=encode(extensions.digest(p_sessao,'sha256'),'hex') and a.session_expira>now() and c.status<>'cancelado';
 if v_id is null then raise exception 'Acesso expirado. Entre novamente pelo link individual' using errcode='42501';end if;
 return v_id;
end $fn$;
revoke all on function private.pre_cadastro_da_sessao_v141(text) from public,anon,authenticated;

create function public.ler_pre_cadastro_v141(p_sessao text)
returns jsonb language plpgsql security definer set search_path='' as $fn$
declare v_id uuid:=private.pre_cadastro_da_sessao_v141(p_sessao);
begin
 return(select jsonb_build_object('id',c.id,'nome_responsavel',c.nome_responsavel,'email',c.email,'secao',s.nome,'status',c.status,'dados',c.dados,'orientacao',c.orientacao,'atualizado_em',c.atualizado_em) from public.pre_cadastros_v141 c join public.secoes s on s.id=c.secao_id where c.id=v_id);
end $fn$;
revoke all on function public.ler_pre_cadastro_v141(text) from public;
grant execute on function public.ler_pre_cadastro_v141(text) to anon,authenticated;

create function private.cpf_valido_v141(p_cpf text)
returns boolean language plpgsql immutable set search_path='' as $fn$
declare v text:=regexp_replace(coalesce(p_cpf,''),'[^0-9]','','g');s integer;d integer;i integer;k integer;
begin
 if length(v)<>11 or v=repeat(substr(v,1,1),11) then return false;end if;
 for k in 10..11 loop s:=0;for i in 1..k-1 loop s:=s+substr(v,i,1)::integer*(k+1-i);end loop;d:=11-(s%11);if d>=10 then d:=0;end if;if d<>substr(v,k,1)::integer then return false;end if;end loop;return true;
end $fn$;
revoke all on function private.cpf_valido_v141(text) from public,anon,authenticated;

