 "textarea", "required": true, "when": {"comportamento_alimentares": true}}, {"key": "comportamento_autoagressao", "label": "Crises em que agrida a si mesmo", "type": "checkbox", "required": false}, {"key": "comportamento_autoagressao_descricao", "label": "Descreva: Crises em que agrida a si mesmo", "type": "textarea", "required": true, "when": {"comportamento_autoagressao": true}}, {"key": "comportamento_sono", "label": "Dificuldades de sono", "type": "checkbox", "required": false}, {"key": "comportamento_sono_descricao", "label": "Descreva: Dificuldades de sono", "type": "textarea", "required": true, "when": {"comportamento_sono": true}}, {"key": "comportamento_agressao", "label": "Crises em que agrida os outros", "type": "checkbox", "required": false}, {"key": "comportamento_agressao_descricao", "label": "Descreva: Crises em que agrida os outros", "type": "textarea", "required": true, "when": {"comportamento_agressao": true}}, {"key": "comportamento_fugas", "label": "Tendência a fugas", "type": "checkbox", "required": false}, {"key": "comportamento_fugas_descricao", "label": "Descreva: Tendência a fugas", "type": "textarea", "required": true, "when": {"comportamento_fugas": true}}, {"key": "comportamento_comunicacao", "label": "Dificuldade de comunicação", "type": "checkbox", "required": false}, {"key": "comportamento_comunicacao_descricao", "label": "Descreva: Dificuldade de comunicação", "type": "textarea", "required": true, "when": {"comportamento_comunicacao": true}}, {"key": "comportamento_ansiedade", "label": "Crises de ansiedade ou pânico", "type": "checkbox", "required": false}, {"key": "comportamento_ansiedade_descricao", "label": "Descreva: Crises de ansiedade ou pânico", "type": "textarea", "required": true, "when": {"comportamento_ansiedade": true}}, {"key": "comportamento_autodestrutivo", "label": "Comportamento autodestrutivo", "type": "checkbox", "required": false}, {"key": "comportamento_autodestrutivo_descricao", "label": "Descreva: Comportamento autodestrutivo", "type": "textarea", "required": true, "when": {"comportamento_autodestrutivo": true}}, {"key": "comportamento_agitacao", "label": "Agitação psicomotora que atrapalhe a concentração", "type": "checkbox", "required": false}, {"key": "comportamento_agitacao_descricao", "label": "Descreva: Agitação psicomotora que atrapalhe a concentração", "type": "textarea", "required": true, "when": {"comportamento_agitacao": true}}]}, {"key": "medica", "title": "Acompanhamento e medicamentos", "fields": [{"key": "transtorno", "label": "Apresenta algum transtorno ou condição?", "type": "select", "required": false, "options": ["Não", "Sim"]}, {"key": "transtorno_descricao", "label": "Descreva", "type": "textarea", "required": true, "when": {"transtorno": "Sim"}}, {"key": "medicacao_transtorno", "label": "Faz uso de medicação para este transtorno?", "type": "select", "required": false, "options": ["Não", "Sim"]}, {"key": "medicacao_transtorno_descricao", "label": "Descreva", "type": "textarea", "required": true, "when": {"medicacao_transtorno": "Sim"}}, {"key": "acompanhamento_profissional", "label": "Faz acompanhamento com profissional?", "type": "select", "required": false, "options": ["Não", "Sim"]}, {"key": "acompanhamento_profissional_descricao", "label": "Descreva", "type": "textarea", "required": true, "when": {"acompanhamento_profissional": "Sim"}}, {"key": "usa_medicamento", "label": "Faz uso de algum medicamento?", "type": "select", "required": false, "options": ["Não", "Sim"]}]}, {"key": "medica", "title": "Informações gerais", "fields": [{"key": "impedimento_fisico", "label": "Possui impedimento físico?", "type": "select", "required": false, "options": ["Não", "Sim"]}, {"key": "impedimento_descricao", "label": "Descreva o impedimento", "type": "textarea", "required": true, "when": {"impedimento_fisico": "Sim"}}, {"key": "restricao_alimentar", "label": "Possui restrição alimentar?", "type": "select", "required": false, "options": ["Não", "Sim"]}, {"key": "restricao_descricao", "label": "Qual é a restrição alimentar?", "type": "textarea", "required": true, "when": {"restricao_alimentar": "Sim"}}, {"key": "sabe_nadar", "label": "Sabe nadar?", "type": "select", "required": false, "options": ["Não", "Sim"]}, {"key": "sonambulo", "label": "É sonâmbulo?", "type": "select", "required": false, "options": ["Não", "Sim"]}, {"key": "plano_saude", "label": "Utiliza plano de saúde?", "type": "select", "required": false, "options": ["Não", "Sim"]}, {"key": "convenio", "label": "Convênio médico", "type": "text", "required": false, "when": {"plano_saude": "Sim"}}, {"key": "carteirinha", "label": "Número da carteirinha", "type": "text", "required": false, "when": {"plano_saude": "Sim"}}, {"key": "medico", "label": "Médico de preferência", "type": "text", "required": false}, {"key": "medico_telefone", "label": "Telefone do médico", "type": "tel", "required": false}, {"key": "conduta_emergencia", "label": "Em caso de emergência, qual conduta deve ser seguida?", "type": "select", "required": true, "options": ["Aceitar decisões médicas", "Aguardar acompanhamento do responsável"]}, {"key": "ciente_emergencia", "label": "Li e compreendi o aviso sobre atendimento de emergência", "type": "checkbox", "required": true, "when": {"conduta_emergencia": "Aguardar acompanhamento do responsável"}}, {"key": "contato_emergencia", "label": "Contato de emergência", "type": "select", "required": true, "options": ["Responsável principal", "Outro"]}, {"key": "contato_nome", "label": "Nome do contato de emergência", "type": "text", "required": true, "when": {"contato_emergencia": "Outro"}}, {"key": "contato_telefone", "label": "Telefone do contato de emergência", "type": "tel", "required": true, "when": {"contato_emergencia": "Outro"}}, {"key": "observacoes", "label": "Há alguma outra informação importante sobre a saúde do jovem?", "type": "textarea", "required": false}]}, {"key": "declaracao", "title": "Conferência e envio", "fields": [{"key": "confirmacao", "label": "Confirmo que conferi os dados e que as informações prestadas são verdadeiras. Estou ciente de que o cadastro depende da conferência da administração e da efetivação do registro UEB.", "type": "checkbox", "required": true}]}], "emergencyNotice": "O grupo entrará em contato com você para acompanhar o jovem e participar das decisões sobre o atendimento. Quando for clinicamente seguro aguardar, será respeitada essa preferência. Em uma emergência, o socorro será acionado imediatamente. As condutas necessárias serão avaliadas pelos profissionais de saúde, conforme a situação e as normas aplicáveis. Esta escolha não representa isenção automática de responsabilidade do grupo."}$json$::jsonb $schema$;
revoke all on function private.pre_cadastro_schema_v141() from public,anon,authenticated;
create function private.validar_pre_cadastro_v141(p_dados jsonb)
returns void language plpgsql set search_path='' as $fn$
declare s jsonb;f jsonb;obj jsonb;v text;active boolean;root text;cond record;d date;item jsonb;
begin
 if jsonb_typeof(p_dados)<>'object' or octet_length(p_dados::text)>150000 then raise exception 'Cadastro inválido ou muito extenso';end if;
 for s in select value from jsonb_array_elements(private.pre_cadastro_schema_v141()->'sections') loop
 root:=s->>'key';obj:=coalesce(p_dados->root,'{}');
 for f in select value from jsonb_array_elements(s->'fields') loop
 active:=true;
 if f ? 'when' then for cond in select * from jsonb_each(f->'when') loop if obj->cond.key is distinct from cond.value then active:=false;end if;end loop;end if;
 if not active then continue;end if;
 v:=btrim(coalesce(obj->>(f->>'key'),''));
 if (f->>'required')::boolean and (v='' or (f->>'type'='checkbox' and obj->(f->>'key') is distinct from 'true'::jsonb)) then raise exception 'Preencha: % — %',s->>'title',f->>'label';end if;
 if length(v)>4000 then raise exception 'Campo muito extenso: %',f->>'label';end if;
 if v<>'' and f->>'type'='email' and v !~ '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$' then raise exception 'E-mail inválido: %',f->>'label';end if;
 if v<>'' and f->>'type'='cpf' and not private.cpf_valido_v141(v) then raise exception 'CPF inválido: %',s->>'title';end if;
 if v<>'' and f->>'type'='date' then
   begin d:=v::date;exception when others then raise exception 'Data inválida: %',f->>'label';end;
   if d>current_date or d<date '1900-01-01' then raise exception 'Confira a data de nascimento';end if;
 end if;
 if v<>'' and f ? 'options' and not (f->'options' ? v) then raise exception 'Opção inválida: %',f->>'label';end if;
 end loop;
 end loop;
 if p_dados->'medica'->>'usa_equipamento'='Sim' and not exists(select 1 from jsonb_each(p_dados->'medica') e where e.key like 'equip_%' and e.value='true'::jsonb) then raise exception 'Selecione pelo menos um equipamento de auxílio';end if;
 if p_dados->'medica'->>'equip_outro_equipamento'='true' and btrim(coalesce(p_dados->'medica'->>'equipamento_descricao',''))='' then raise exception 'Descreva o outro equipamento';end if;
 if p_dados->'medica'->>'problema_cronico'='Sim' and not exists(select 1 from jsonb_each(p_dados->'medica') e where e.key like 'cronico_%' and e.value='true'::jsonb) then raise exception 'Selecione a condição crônica';end if;
 if p_dados->'medica'->>'usa_medicamento'='Sim' then
   if jsonb_typeof(p_dados->'medica'->'medicamentos') is distinct from 'array' then raise exception 'Adicione os medicamentos';end if;
   if jsonb_array_length(p_dados->'medica'->'medicamentos') not between 1 and 20 then raise exception 'Adicione de 1 a 20 medicamentos';end if;
   for item in select value from jsonb_array_elements(p_dados->'medica'->'medicamentos') loop
     if btrim(coalesce(item->>'nome',''))='' or length(item->>'nome')>160 or length(coalesce(item->>'informacoes',''))>2000 then raise exception 'Confira o nome e as informações dos medicamentos';end if;
   end loop;
 end if;
end $fn$;
revoke all on function private.validar_pre_cadastro_v141(jsonb) from public,anon,authenticated;

create function public.salvar_pre_cadastro_v141(p_sessao text,p_dados jsonb,p_enviar boolean,p_versao timestamptz)
returns jsonb language plpgsql security definer set search_path='' as $fn$
declare v_id uuid:=private.pre_cadastro_da_sessao_v141(p_sessao);c public.pre_cadastros_v141%rowtype;v_now timestamptz:=clock_timestamp();
begin
 select * into c from public.pre_cadastros_v141 where id=v_id for update;
 if c.status not in('rascunho','ajustes') then raise exception 'Cadastro enviado. Aguarde a conferência da administração';end if;
 if c.atualizado_em is distinct from p_versao then raise exception 'O cadastro mudou. Recarregue antes de salvar para não sobrescrever alterações';end if;
 if jsonb_typeof(p_dados)<>'object' or octet_length(p_dados::text)>150000 then raise exception 'Dados inválidos ou muito extensos';end if;
 if p_enviar then
   perform private.validar_pre_cadastro_v141(p_dados);
   if lower(btrim(p_dados->'responsavel'->>'email'))<>lower(c.email) then raise exception 'O e-mail do responsável deve ser o informado no convite. Peça a correção à administração';end if;
 end if;
 update public.pre_cadastros_v141 set dados=p_dados,status=case when p_enviar then 'enviado' else status end,atualizado_em=v_now,enviado_em=case when p_enviar then v_now else enviado_em end,
 emergencia_ciente_em=case when p_enviar and p_dados->'medica'->>'ciente_emergencia'='true' then v_now else null end,
 emergencia_termo_versao=case when p_enviar and p_dados->'medica'->>'ciente_emergencia'='true' then 1 else null end where id=v_id;
 if p_enviar then
   insert into public.notificacoes(user_id,tipo,titulo,mensagem,secao_id)
   select user_id,'pre_cadastro','Novo cadastro aguardando conferência','Um responsável enviou um novo pré-cadastro. Abra Novos cadastros para conferir.',c.secao_id from public.perfis_usuarios where tipo='administrador' and ativo;
 end if;
 return public.ler_pre_cadastro_v141(p_sessao);
end $fn$;
revoke all on function public.salvar_pre_cadastro_v141(text,jsonb,boolean,timestamptz) from public;
grant execute on function public.salvar_pre_cadastro_v141(text,jsonb,boolean,timestamptz) to anon,authenticated;

create function public.admin_pre_cadastro_v141(p_id uuid,p_acao text,p_versao timestamptz,p_motivo text default null,p_registro text default null,p_validade date default null)
returns jsonb language plpgsql security definer set search_path='' as $fn$
declare c public.pre_cadastros_v141%rowtype;v_ramo bigint;v_resp bigint;v_jovem bigint;j jsonb;r jsonb;m jsonb;v_med jsonb;v_pair record;v_summary text;v_existing public.responsaveis%rowtype;
begin
 if auth.uid() is null or not private.sou_admin() then raise exception 'Acesso reservado à administração' using errcode='42501';end if;
 select * into c from public.pre_cadastros_v141 where id=p_id for update;
 if not found then raise exception 'Pré-cadastro não encontrado';end if;
 if c.atualizado_em is distinct from p_versao then raise exception 'O cadastro foi atualizado. Reabra antes de continuar';end if;
 if c.status in('cancelado','liberado') then raise exception 'Este cadastro já foi concluído ou cancelado';end if;
 if p_acao='novo_link' then raise exception 'Para substituir um link, cancele este cadastro e gere outro';end if;
 if p_acao='cancelar' then update public.pre_cadastros_v141 set status='cancelado',atualizado_em=clock_timestamp() where id=p_id;
 elsif p_acao='ajustes' then
   if c.status not in('enviado','conferido') or length(btrim(coalesce(p_motivo,'')))<3 then raise exception 'Informe a correção após receber o cadastro';end if;
   update public.pre_cadastros_v141 set status='ajustes',orientacao=btrim(p_motivo),atualizado_em=clock_timestamp() where id=p_id;
 elsif p_acao in('conferido','paxtu','boleto','aguardando_ueb') then
   if not ((p_acao='conferido' and c.status='enviado') or(p_acao='paxtu' and c.status='conferido') or(p_acao='boleto' and c.status='paxtu') or(p_acao='aguardando_ueb' and c.status in('paxtu','boleto'))) then raise exception 'Conclua a etapa anterior primeiro';end if;
   update public.pre_cadastros_v141 set status=p_acao,atualizado_em=clock_timestamp() where id=p_id;
 elsif p_acao='liberar' then
   if c.status<>'aguardando_ueb' or btrim(coalesce(p_registro,'')) !~ '^[0-9]{4,12}([-/][0-9])?$' or p_validade is null or p_validade<current_date then raise exception 'Confirme o registro UEB e informe número e validade vigentes';end if;
   perform private.validar_pre_cadastro_v141(c.dados);
   j:=c.dados->'jovem';r:=c.dados->'responsavel';m:=c.dados->'medica';
   if exists(select 1 from public.jovens where registro_paxtu=btrim(p_registro) or dados_cadastrais->>'cpf'=j->>'cpf' or (lower(btrim(nome_completo))=lower(btrim(j->>'nome')) and data_nascimento=(j->>'nascimento')::date and not eh_teste)) then raise exception 'Já existe um jovem com esses dados ou registro. Confira antes de duplicar';end if;
   if (select count(*) from public.responsaveis where lower(btrim(email))=lower(c.email) and not eh_teste)>1 then raise exception 'Há responsáveis duplicados com esse e-mail. Corrija antes de liberar';end if;
   select * into v_existing from public.responsaveis where lower(btrim(email))=lower(c.email) and not eh_teste;
   if found then
     if lower(btrim(v_existing.nome_completo))<>lower(btrim(r->>'nome')) then raise exception 'O e-mail já pertence a outro cadastro. Confira a identidade antes de vincular';end if;
     if coalesce(v_existing.dados_cadastrais->>'cpf','')<>'' and regexp_replace(v_existing.dados_cadastrais->>'cpf','[^0-9]','','g')<>regexp_replace(r->>'cpf','[^0-9]','','g') then raise exception 'CPF diverge do responsável existente';end if;
     v_resp:=v_existing.id;
     update public.responsaveis set dados_cadastrais=r where id=v_resp;
   else
     if exists(select 1 from auth.users where lower(email)=lower(c.email)) then raise exception 'Este e-mail já possui outra conta no Conecta. A administração precisa conferir o vínculo';end if;
     insert into public.responsaveis(nome_completo,email,telefone,dados_cadastrais) values(btrim(r->>'nome'),lower(c.email),r->>'celular',r) returning id into v_resp;
   end if;
   select ramo_id into v_ramo from public.secoes where id=c.secao_id and ativo;
   if v_ramo is null then raise exception 'A seção selecionada não está ativa';end if;
   insert into public.jovens(nome_completo,data_nascimento,secao_id,ramo_id,registro_paxtu,validade_registro,ativo,dados_cadastrais)
   values(btrim(j->>'nome'),(j->>'nascimento')::date,c.secao_id,v_ramo,btrim(p_registro),p_validade,true,j) returning id into v_jovem;
   insert into public.jovem_responsaveis(jovem_id,responsavel_id,parentesco,responsavel_principal) values(v_jovem,v_resp,r->>'parentesco',true);
   v_med:=jsonb_build_object('altura',m->>'altura','peso',m->>'peso','tipo_sanguineo',m->>'sangue','fator_rh',m->>'rh','restricao_alimentar_marcado',m->>'restricao_alimentar'='Sim','restricao_alimentar',m->>'restricao_descricao','sonambulo_marcado',m->>'sonambulo'='Sim','sabe_nadar',case m->>'sabe_nadar' when 'Sim' then 'sim' when 'Não' then 'nao' else '' end,'medicamentos',coalesce(m->'medicamentos','[]'),'pre_cadastro_original',m);
   for v_pair in select * from jsonb_each_text($mapping${"equip_oculos": "equipamento_oculos", "equip_lentes": "equipamento_lentes_contato", "equip_aparelho_dentario": "equipamento_aparelho_dentario", "equip_sonda": "equipamento_sonda", "equip_marca_passos": "equipamento_marcapasso", "equip_aparelho_auditivo": "equipamento_aparelho_audicao", "equip_bomba_insulina": "equipamento_bomba_insulina", "equip_outro_equipamento": "equipamento_outros", "alergia_acaro": "alergia_acaros", "alergia_alimentos": "alergia_alimentos", "alergia_fungos": "alergia_fungos", "alergia_insetos": "alergia_picada_inseto", "alergia_plantas": "alergia_plantas", "alergia_medicamentos": "alergia_medicamentos", "alergia_outros": "alergia_outro", "condicao_fisica": "deficiencia_fisica", "condicao_visual": "deficiencia_visual", "condicao_auditiva": "deficiencia_auditiva", "condicao_intelectual": "deficiencia_intelectual", "condicao_autismo": "deficiencia_autismo", "comportamento_instrucoes": "comp_instrucao_verbal", "comportamento_alimentares": "comp_alimentares", "comportamento_autoagressao": "comp_autoagressao", "comportamento_sono": "comp_sono", "comportamento_agressao": "comp_agressao_outros", "comportamento_fugas": "comp_fugas", "comportamento_comunicacao": "comp_comunicacao", "comportamento_ansiedade": "comp_ansiedade_panico", "comportamento_autodestrutivo": "comp_autodestrutivo", "comportamento_agitacao": "comp_agitacao", "cronico_hipertensao": "saude_hipertensao", "cronico_diabetes": "saude_diabetes", "cronico_epilepsia": "saude_convulsoes_epilepsia", "cronico_dermatologicos": "saude_dermatologicos", "cronico_cardiacos": "saude_cardiacos", "cronico_reumatologicos": "saude_reumatologicos", "cronico_hematologicos": "saude_hematologicos", "cronico_outros": "saude_outros"}$mapping$::jsonb) loop
     v_med:=v_med||jsonb_build_object(v_pair.value||'_marcado',coalesce(m->v_pair.key,'false'::jsonb),v_pair.value,coalesce(m->>(v_pair.key||'_descricao'),case when v_pair.key like 'cronico_%' then m->>'cronico_descricao' when v_pair.key like 'equip_%' then m->>'equipamento_descricao' else '' end));
   end loop;
   v_med:=v_med||jsonb_build_object('saude_asma_bronquite_marcado',m->>'cronico_asma'='true' or m->>'cronico_bronquite'='true','saude_rinite_sinusite_marcado',m->>'cronico_sinusite'='true','mental_transtorno_marcado',m->>'transtorno'='Sim','mental_transtorno',m->>'transtorno_descricao','mental_medicacao_marcado',m->>'medicacao_transtorno'='Sim','mental_medicacao',m->>'medicacao_transtorno_descricao','mental_outro_profissional_marcado',m->>'acompanhamento_profissional'='Sim','mental_outro_profissional',m->>'acompanhamento_profissional_descricao','impedimento_fisico_marcado',m->>'impedimento_fisico'='Sim','impedimento_fisico',m->>'impedimento_descricao','sabe_nadar_marcado',m->>'sabe_nadar'='Sim','medico_preferencia',m->>'medico','emergencia_conduta',case when m->>'conduta_emergencia'='Aguardar acompanhamento do responsável' then 'aguardar_pais' else 'aceita_decisoes_medicas' end,'avisar_emergencia',case when m->>'contato_emergencia'='Outro' then 'outro' else 'pais' end,'emergencia_outro',m->>'contato_nome','telefone_emergencia',case when m->>'contato_emergencia'='Outro' then m->>'contato_telefone' else r->>'celular' end);
   select string_agg((f->>'label')||': '||(m->>(f->>'key')),E'\n') into v_summary from jsonb_array_elements(private.pre_cadastro_schema_v141()->'sections') s cross join lateral jsonb_array_elements(s->'fields') f where s->>'key'='medica' and f->>'type'<>'checkbox' and coalesce(m->>(f->>'key'),'')<>'';
   insert into public.fichas_medicas(jovem_id,tipo_sanguineo,alergias,medicamentos_uso_continuo,restricoes_alimentares,condicoes_relevantes,plano_saude,numero_carteirinha,contato_emergencia_nome,contato_emergencia_telefone,observacoes,dados_completos,responsavel_confirmou,confirmado_em)
   values(v_jovem,concat(nullif(m->>'sangue','Não sei'),nullif(m->>'rh','Não sei')),null,null,m->>'restricao_descricao',v_summary,m->>'convenio',m->>'carteirinha',case when m->>'contato_emergencia'='Responsável principal' then r->>'nome' else m->>'contato_nome' end,case when m->>'contato_emergencia'='Responsável principal' then r->>'celular' else m->>'contato_telefone' end,m->>'observacoes',v_med,true,c.enviado_em);
   update public.pre_cadastros_v141 set status='liberado',jovem_id=v_jovem,responsavel_id=v_resp,registro_ueb=btrim(p_registro),validade_registro=p_validade,atualizado_em=clock_timestamp() where id=p_id;
 else raise exception 'Ação inválida';end if;
 return(select jsonb_build_object('id',id,'status',status,'responsavel_id',responsavel_id,'jovem_id',jovem_id) from public.pre_cadastros_v141 where id=p_id);
end $fn$;
revoke all on function public.admin_pre_cadastro_v141(uuid,text,timestamptz,text,text,date) from public,anon;
grant execute on function public.admin_pre_cadastro_v141(uuid,text,timestamptz,text,text,date) to authenticated;
create function public.renovar_link_pre_cadastro_v141(p_id uuid)
returns text language plpgsql security definer set search_path='' as $fn$
declare v_token text;
begin
 if auth.uid() is null or not private.sou_admin() then raise exception 'Acesso reservado à administração' using errcode='42501';end if;
 perform 1 from public.pre_cadastros_v141 where id=p_id and status not in('liberado','cancelado') for update;
 if not found then raise exception 'Cadastro não disponível';end if;
 v_token:=encode(extensions.gen_random_bytes(32),'hex');
 update private.pre_cadastro_acessos_v141 set token_hash=encode(extensions.digest(v_token,'sha256'),'hex'),senha_hash=null,session_hash=null,session_expira=null,tentativas=0,bloqueado_ate=null,expira_em=now()+interval '30 days' where id=p_id;
 return v_token;
end $fn$;
revoke all on function public.renovar_link_pre_cadastro_v141(uuid) from public,anon;
grant execute on function public.renovar_link_pre_cadastro_v141(uuid) to authenticated;
